# ── (g2) partie 2 : la reprise prévue dans « Où on en est » (cliquable → oral prérempli) ; le chapitre : l'alerte sur l'heure à venir et « manquante pour la suite »
s=open(p,encoding='utf-8').read()
rep("  const d = $('durees'); poserHtml(d, lignes.join(''));","  const d = $('durees'); poserHtml(d, lignes.join('') + reprisesPrevuesHtml()); d.querySelectorAll('[data-reprise]').forEach(l => l.onclick = () => { const q = ((S.reprisesPrevues || {})[S.heure] || []).find(x => x.notion === l.dataset.reprise); ouvrirOral({ act: null, notion: l.dataset.reprise, texte: '' }); if (q) journal('reprise-prevue-ouverte', { notion: q.notion }); });")
rep("aVenir.forEach(h => { const sim = HEURES_SIM[h]; const prevu = E.filter(e => e.heure === h).map(e => e.act).slice(0, 4); h1 += `<div class=\"chap-h avenir\"><div class=\"chap-t\"><b>Heure ${h}</b> — ${sim ? esc(sim.jour) : 'à venir'} · <i>à venir : la trame prévoit</i> ${prevu.map(esc).join(', ')}…</div></div>`; });",
    "aVenir.forEach(h => { const sim = HEURES_SIM[h]; const prevu = E.filter(e => e.heure === h).map(e => e.act).slice(0, 4); const rm = remobNonTravaillees(h); h1 += `<div class=\"chap-h avenir\"><div class=\"chap-t\"><b>Heure ${h}</b> — ${sim ? esc(sim.jour) : 'à venir'} · <i>à venir : la trame prévoit</i> ${prevu.map(esc).join(', ')}…</div>${rm.map(r => `<div class=\"chap-alerte\">⚠ « ${esc(r.act)} » remobilise <b>${esc(r.lib)}</b> — <b>non travaillée</b>${r.source ? ' (« ' + esc(r.source.titre) + ' » ' + esc(r.sourceEtat) + ')' : ''}. À régler à l'ouverture de l'heure ${h}.</div>`).join('')}</div>`; });")
rep("const ligneN = (n, f) => { const pv = prevues[n.id] || [], vu = vues[n.id] || [], dn = donnees[n.id] || []; const etat = vu.length ? 'travaillée' : (pv.some(x => aVenir.includes(x.h)) ? 'à venir' : (pv.length ? 'non travaillée' : (imprev[n.id] ? 'imprévue' : '')));",
    "const manquantes = {}; aVenir.forEach(h => remobNonTravaillees(h).forEach(r => { manquantes[r.id] = manquantes[r.id] || []; manquantes[r.id].push({ h, act: r.act }); }));\n  const ligneN = (n, f) => { const pv = prevues[n.id] || [], vu = vues[n.id] || [], dn = donnees[n.id] || []; const etat = manquantes[n.id] && !vu.length ? 'manquante pour la suite' : vu.length ? 'travaillée' : (pv.some(x => aVenir.includes(x.h)) ? 'à venir' : (pv.length ? 'non travaillée' : (imprev[n.id] ? 'imprévue' : '')));")
rep("if (!pv.length && !vu.length && !dn.length && !imprev[n.id]) return '';","if (!pv.length && !vu.length && !dn.length && !imprev[n.id] && !manquantes[n.id]) return '';")
rep("${imprev[n.id] ? ' · <i>imprévue, ajoutée pendant l\\'heure</i>' : ''}</div>`; };","${imprev[n.id] ? ' · <i>imprévue, ajoutée pendant l\\'heure</i>' : ''}${manquantes[n.id] && !vu.length ? ' · <i>attendue par ' + manquantes[n.id].map(x => '« ' + esc(x.act) + ' » (heure ' + x.h + ')').join(', ') + '</i>' : ''}</div>`; };")
