rep("const vues = {}; J.filter(x => x.type === 'diapo' && E[x.di]).forEach(x => { (E[x.di].comp || []).forEach(id => { vues[id] = vues[id] || []; vues[id].push({ h: x.h, act: E[x.di].act }); }); }); Object.keys(S.notionsOral || {}).forEach(id => { const o = S.notionsOral[id]; vues[id] = vues[id] || []; vues[id].push({ h: o.h, act: (o.par || 'à l\\'oral') + (o.par && /oral/.test(o.par) ? '' : ' (à l\\'oral)') }); });","const vues = {}; const trav = notionsTravaillees(); Object.keys(trav).forEach(id => { const t = trav[id]; vues[id] = [{ h: t.h, act: (t.par || '') + (t.oral && !/oral/.test(t.par || '') ? ' (à l\\'oral)' : '') }]; });")
